mapper.select:
select id, municipality_id as municipalityId, holiday_date, name_fr, name_en, name_zh, shift_days, sector, source_url, active
from collection_holiday
where municipality_id = #{municipalityId}
  and active = true
  and holiday_date >= #{from}
order by holiday_date asc

select id, municipality_id as municipalityId, holiday_date, name_fr, name_en, name_zh, shift_days, sector, source_url, active
from collection_holiday
where id = #{id}

select id, municipality_id as municipalityId, holiday_date, name_fr, name_en, name_zh, shift_days, sector, source_url, active
from collection_holiday
where municipality_id = #{municipalityId}
  and holiday_date = #{holidayDate}
  and sector = #{sector}
